/*
 * PwdHash v2 — extended character set.
 *
 * This is a fork-local extension, NOT part of upstream Stanford PwdHash.
 * Built on the audited core_hmac_md5() from md5.js (unchanged).
 *
 * Spec (locked by tests/extended-hashing.test.js golden vectors, generated by
 * tests/helpers/reference-v2.py):
 *
 *   - the password is used LITERALLY ("@@" stripping belongs to the form
 *     layer — done once in Generate(); stripping here again was a bug)
 *   - L = max(12, 2n + 2), n = password.length (UTF-16 code units)
 *   - stream = HMAC-MD5(key=utf8(password),
 *                        data=utf8("PwdHash-2|" + realm + "|" + i))
 *     for i = 0, 1, 2, ... (16 bytes per block; realm is the extracted domain,
 *     already lowercased when the case-insensitive switch is on)
 *   - draw chars by rejection sampling on stream bytes (unbiased):
 *     accept byte b iff b < floor(256 / len(set)) * len(set)
 *   - force positions 0..3 to one lower / upper / digit / special char,
 *     then Fisher-Yates shuffle over all L positions with unbiased indices
 *     from the same stream
 *
 * UTF-8 note: core_hmac_md5() takes JS strings and keys on the low byte of
 * each UTF-16 code unit — wrong for non-ASCII. SPH_utf8Encode() converts the
 * password and message to explicit UTF-8 bytes first (WTF-8 3-byte form for
 * lone surrogates, matching Python's 'surrogatepass'), so the hash is
 * reproducible across implementations and languages.
 *
 * The "PwdHash-2|" tag is domain separation: v1 and v2 outputs are distinct
 * by construction; a future revision would use "PwdHash-3|".
 *
 * Output alphabet (86 chars): A-Z a-z 0-9 plus
 *   ! @ # $ % ^ & * ( ) - _ = + [ ] { } : ; , . ? /
 * (no quotes, backslash or space — survives HTML attributes, shell copy-paste
 * and strict site validators.)
 */

var SPH_kV2Lower = 'abcdefghijklmnopqrstuvwxyz';
var SPH_kV2Upper = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
var SPH_kV2Digit = '0123456789';
var SPH_kV2Special = '!@#$%^&*()-_=+[]{}:;,.?/';
var SPH_kV2Alphabet = SPH_kV2Lower + SPH_kV2Upper + SPH_kV2Digit + SPH_kV2Special;
var SPH_kV2Tag = 'PwdHash-2|';

/*
 * UTF-8 encode a JS string into a "binary string" (one char per byte) so
 * core_hmac_md5's low-byte str2binl produces correct UTF-8 bytes.
 * Surrogate pairs become 4-byte sequences; lone surrogates (impossible in
 * normal DOM input) get the WTF-8 3-byte form = Python 'surrogatepass'.
 */
function SPH_utf8Encode(s) {
  var out = '';
  for (var i = 0; i < s.length; i++) {
    var c = s.charCodeAt(i);
    if (c < 0x80) {
      out += String.fromCharCode(c);
    } else if (c < 0x800) {
      out += String.fromCharCode(0xC0 | (c >> 6), 0x80 | (c & 0x3F));
    } else if (c >= 0xD800 && c < 0xDC00 && i + 1 < s.length &&
               s.charCodeAt(i + 1) >= 0xDC00 && s.charCodeAt(i + 1) < 0xE000) {
      // surrogate pair -> 4-byte UTF-8
      var cp = 0x10000 + ((c - 0xD800) << 10) + (s.charCodeAt(++i) - 0xDC00);
      out += String.fromCharCode(0xF0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3F),
                                 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F));
    } else {
      // BMP 3-byte UTF-8 (also the WTF-8 form for lone surrogates)
      out += String.fromCharCode(0xE0 | (c >> 12), 0x80 | ((c >> 6) & 0x3F),
                                 0x80 | (c & 0x3F));
    }
  }
  return out;
}

function SPH_ExtendedHashedPassword(password, realm) {
  var L = Math.max(12, 2 * password.length + 2);

  // UTF-8 byte strings (one char per byte) for the HMAC. core_hmac_md5's
  // str2binl takes the low byte of each code unit, so passing raw non-ASCII
  // strings would key on garbage — encode explicitly.
  var key = SPH_utf8Encode(password);

  // Lazy byte stream over HMAC-MD5 blocks.
  var blocks = [];
  var counter = 0;
  function nextByte() {
    while (blocks.length == 0) {
      var msg = SPH_utf8Encode(SPH_kV2Tag + realm + '|' + counter++);
      var words = core_hmac_md5(key, msg);
      for (var w = 0; w < words.length; w++) {
        // core_hmac_md5 packs the digest little-endian per 32-bit word
        blocks.push(words[w] & 0xff, (words[w] >>> 8) & 0xff,
                    (words[w] >>> 16) & 0xff, (words[w] >>> 24) & 0xff);
      }
    }
    return blocks.shift();
  }
  function drawFrom(set) {
    var limit = 256 - (256 % set.length);
    var b;
    do { b = nextByte(); } while (b >= limit);
    return set.charAt(b % set.length);
  }
  function drawIndex(n) {
    var limit = 256 - (256 % n);
    var b;
    do { b = nextByte(); } while (b >= limit);
    return b % n;
  }

  var chars = [];
  for (var i = 0; i < L; i++) chars.push(drawFrom(SPH_kV2Alphabet));
  chars[0] = drawFrom(SPH_kV2Lower);
  chars[1] = drawFrom(SPH_kV2Upper);
  chars[2] = drawFrom(SPH_kV2Digit);
  chars[3] = drawFrom(SPH_kV2Special);
  for (var i = L - 1; i > 0; i--) {
    var j = drawIndex(i + 1);
    var t = chars[i]; chars[i] = chars[j]; chars[j] = t;
  }
  return chars.join('');
}
